css:
@import url("https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap");
:root{--vio:#7C5CFC;--vio-d:#6346E6;--vio-l:#F1EDFF;--pink:#FF7EB6;--mint:#2DD4A7;--sun:#FFC24B;--text:#2B2A3D;--muted:#76758A;--line:#ECEAF3;--bg:#F7F6FB;--card:#fff;
--font:"Nunito",system-ui,-apple-system,"Segoe UI",sans-serif}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:var(--font);font-size:15px;line-height:1.5;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
a{color:inherit}img{display:block;max-width:100%}h1,h2,h3{margin:0;color:#1D1C2E;font-weight:800}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--vio);color:#fff;padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--vio);outline-offset:2px;border-radius:8px}
.app{display:grid;grid-template-columns:236px 1fr;min-height:100vh}
.side{background:var(--card);padding:22px 16px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column;border-right:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:10px;font-weight:900;font-size:20px;text-decoration:none;padding:0 8px 24px;color:#1D1C2E}
.brand i{width:32px;height:32px;border-radius:12px;background:var(--vio)}
.nav-l{list-style:none;padding:0;margin:0}
.nav-l a{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;text-decoration:none;font-weight:700;color:var(--muted);margin-bottom:2px}
.nav-l a:hover{background:var(--bg);color:var(--text)}.nav-l a.on{background:var(--vio);color:#fff}
.nav-l span{width:22px;text-align:center}
.help{margin-top:auto;background:var(--vio-l);border-radius:16px;padding:16px;font-size:14px}.help b{display:block;color:var(--vio-d)}
.main{min-width:0;padding:24px 28px 40px}
.top{display:flex;align-items:center;gap:14px;margin-bottom:22px;flex-wrap:wrap}
.menu-btn{display:none;background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}
.top h1{font-size:26px;font-weight:900}.top p{margin:2px 0 0;color:var(--muted)}
.top .r{margin-left:auto;display:flex;gap:10px;align-items:center}
.btn{display:inline-flex;align-items:center;gap:6px;padding:10px 16px;border-radius:12px;font-weight:800;font-size:14px;border:1px solid var(--line);background:#fff;cursor:pointer;font-family:var(--font);color:var(--text)}
.btn.pri{background:var(--vio);border-color:var(--vio);color:#fff}
.top img{width:40px;height:40px;border-radius:12px;object-fit:cover}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}
.card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:20px}
.kpi{display:flex;gap:14px;align-items:center}
.kpi .ic{width:48px;height:48px;border-radius:16px;display:grid;place-items:center;font-size:22px;flex:none}
.kpi small{color:var(--muted);font-weight:700}.kpi .v{font-size:26px;font-weight:900;color:#1D1C2E}
.kpi .d{font-size:13px;font-weight:700;color:#15A37E}
.row{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-bottom:14px}
.row3{display:grid;grid-template-columns:1.6fr 1fr;gap:14px}
.card-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;gap:10px;flex-wrap:wrap}
.card h2{font-size:17px}
.hbars .b{display:grid;grid-template-columns:120px 1fr 40px;gap:10px;align-items:center;margin-bottom:12px;font-size:14px;font-weight:700}
.hbars .t{height:14px;background:var(--bg);border-radius:8px;overflow:hidden}.hbars .t i{display:block;height:100%;border-radius:8px}
.leave{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.leave:last-child{border:0}
.leave img{width:40px;height:40px;border-radius:12px;object-fit:cover}
.leave div{flex:1;min-width:0}.leave b{display:block;font-size:14px}.leave small{color:var(--muted)}
.leave .acts{display:flex;gap:6px}
.leave button{border:0;border-radius:10px;padding:7px 12px;font:inherit;font-weight:800;font-size:13px;cursor:pointer}
.ok{background:#E3F8F1;color:#15A37E}.no{background:#FFE8F1;color:#D6336C}
.leave .done{font-size:13px;font-weight:800}
.att{display:flex;align-items:center;gap:18px}
.att svg{width:150px;height:150px;flex:none}
.att ul{list-style:none;padding:0;margin:0;flex:1;font-size:14px}.att li{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--line)}
.att li i{display:inline-block;width:10px;height:10px;border-radius:4px;margin-right:8px}
.dir-h{display:flex;gap:10px;flex-wrap:wrap}
.dir-h input,.dir-h select{border:1px solid var(--line);background:var(--bg);border-radius:12px;padding:9px 12px;font:inherit;font-size:14px;color:var(--text)}
.dir-h input{width:200px}
.people{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.person{border:1px solid var(--line);border-radius:16px;padding:14px;display:flex;gap:12px;align-items:center}
.person img{width:48px;height:48px;border-radius:14px;object-fit:cover}
.person b{display:block;font-size:14px}.person small{color:var(--muted);display:block}
.dept{display:inline-block;font-size:11px;font-weight:800;border-radius:6px;padding:1px 7px;margin-top:4px}
.side-list h2{margin-bottom:10px}
.cel{display:flex;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}.cel:last-child{border:0}
.cel .e{width:38px;height:38px;border-radius:12px;background:var(--vio-l);display:grid;place-items:center;font-size:18px}
.cel small{display:block;color:var(--muted)}
.roles{margin-top:16px}.role{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px dashed var(--line);font-size:14px}.role b{color:var(--vio-d)}
.foot{color:var(--muted);font-size:13px;margin-top:24px;text-align:center}.foot a{color:var(--vio)}
@media (max-width:1150px){.kpis{grid-template-columns:1fr 1fr}.row,.row3{grid-template-columns:1fr}.people{grid-template-columns:1fr 1fr}}
@media (max-width:860px){.app{grid-template-columns:1fr}.side{position:fixed;left:0;top:0;width:250px;z-index:30;transform:translateX(-100%);transition:transform .25s}.side.open{transform:none}.menu-btn{display:block}.main{padding:18px 14px}}
@media (max-width:540px){.kpis,.people{grid-template-columns:1fr}.att{flex-direction:column}.hbars .b{grid-template-columns:90px 1fr 34px}}

javascript:
const D=[["Engineering",82,"#7C5CFC"],["Sales",54,"#FF7EB6"],["Support",41,"#2DD4A7"],["Marketing",28,"#FFC24B"],["Finance",18,"#5B8DEF"],["Operations",25,"#A78BFA"]];
document.getElementById('hbars').innerHTML=D.map(d=>`<div class="b"><span>${d[0]}</span><div class="t"><i style="width:${d[1]/82*100}%;background:${d[2]}"></i></div><span>${d[1]}</span></div>`).join('');
const L=[["Sam Okoye","Annual leave · 20 to 24 Oct (5 days)","1507003211169-0a1dd7228f2d"],["Grace Liu","Sick leave · 15 Oct (1 day)","1438761681033-6461ffad8d80"],["Tom Becker","Parental leave · from 3 Nov","1500648767791-00dcc994a43e"]];
let waiting=L.length;const le=document.getElementById('leaves');
le.innerHTML=L.map((l,i)=>`<div class="leave"><img src="https://images.unsplash.com/photo-${l[2]}?w=80&q=60&auto=format&fit=crop" alt="" width="40" height="40"><div><b>${l[0]}</b><small>${l[1]}</small></div><div class="acts" id="a${i}"><button class="ok" type="button" data-i="${i}" data-v="Approved">Approve</button><button class="no" type="button" data-i="${i}" data-v="Declined">Decline</button></div></div>`).join('');
le.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=document.getElementById('a'+b.dataset.i);a.innerHTML=`<span class="done" style="color:${b.dataset.v==='Approved'?'#15A37E':'#D6336C'}">${b.dataset.v}</span>`;waiting--;document.getElementById('lcount').textContent=waiting?waiting+' waiting':'All done'});
const C={Engineering:["#F1EDFF","#6346E6"],Sales:["#FFE8F1","#D6336C"],Marketing:["#FFF4DB","#B7791F"],Support:["#E3F8F1","#15A37E"],Finance:["#E7EEFD","#3B6FD8"]};
const E=[["Lena Park","Product designer","Engineering","1494790108377-be9c29b29330"],["David Chen","Account executive","Sales","1507003211169-0a1dd7228f2d"],["Emily Hart","Content lead","Marketing","1438761681033-6461ffad8d80"],["Marcus Bell","Support manager","Support","1500648767791-00dcc994a43e"],["Aiko Tanaka","Frontend developer","Engineering","1534528741775-53994a69daeb"],["Ravi Kapoor","Financial analyst","Finance","1506794778202-cad84cf45f1d"],["Sofia Grant","Sales manager","Sales","1544005313-94ddf0286df2"],["Leo Brandt","Backend developer","Engineering","1535713875002-d1d0cf377fde"],["Nina Rossi","Support specialist","Support","1573496359142-b8d87734a5a2"]];
function dir(){const q=document.getElementById('q').value.toLowerCase(),dp=document.getElementById('dp').value;
document.getElementById('people').innerHTML=E.filter(e=>(!q||(e[0]+e[1]).toLowerCase().includes(q))&&(!dp||e[2]===dp)).map(e=>`<div class="person"><img src="https://images.unsplash.com/photo-${e[3]}?w=100&q=60&auto=format&fit=crop" alt="" width="48" height="48" loading="lazy"><div><b>${e[0]}</b><small>${e[1]}</small><span class="dept" style="background:${C[e[2]][0]};color:${C[e[2]][1]}">${e[2]}</span></div></div>`).join('')||'<p style="color:var(--muted)">No one matches that search.</p>'}
['q','dp'].forEach(id=>document.getElementById(id).addEventListener('input',dir));dir();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
